                                        </span>
                                        <span className="truncate">{item.label}</span>
                                        {item.badge && (
                                            <span className="ml-auto text-[10px] px-1.5 py-0.5 rounded-full bg-red-500 text-white font-bold flex-shrink-0">
                                                {item.badge}
                                            </span>
                                        )}
                                    </Link>
                                );
                            })}
                        </div>
                    ))}
